/**
 * Thrown by `fire.followup` when the wake message was not sent. A handler can
 * fire again later without a double wake. Any other error from `followup`
 * can come after the message started a turn.
 */
export class ReminderFollowupNotSentError extends Error {
    constructor(reason, message, options) {
        super(message, options);
        this.name = "ReminderFollowupNotSentError";
        this.reason = reason;
    }
}
